-- Aline Dan · Catálogo de serviços (73 itens)
--
-- Pode rodar quantas vezes quiser: não apaga nada e atualiza o que já existe.
-- É de propósito. O migrate-v3 apagava a tabela antes de inserir, e uma
-- importação interrompida no meio deixava o catálogo vazio — o site subia,
-- respondia 200 e não mostrava serviço nenhum.
--
-- Fonte: trinks.com/espaco-lounge-aline-dan

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
  name = VALUES(name), category = VALUES(category), description = VALUES(description),
  duration_min = VALUES(duration_min), price = VALUES(price), price_from = VALUES(price_from),
  icon = VALUES(icon), active = VALUES(active), sort_order = VALUES(sort_order);
